(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ku"] = {"ui":{"skip":"Derbasî naverokê bibe","back":"← Vegere AI-gile","lang.button":"Ziman: {name}","lang.dialog":"Zimanek hilbijêre","lang.search":"Li zimanan bigere","lang.none":"Tu ziman nehat dîtin","lang.notYet":"{name} hê nehatiye wergerandin","theme.aria":"Rûpelê biguherîne: ronî, tarî an reş","theme.toLight":"Biguherîne rûpela ronî","theme.toDark":"Biguherîne rûpela tarî","theme.toBlack":"Biguherîne rûpela reş (reşa rastîn, ji bo ekranên OLED rehet)","words.underline":"Van peyvan li ser rûpelê bin xet bike","words.underlineHelp":"Mişkê bibe ser peyveke bi xêza xalxalî an lê bitikîne, da ku wateya wê bibînî.","index.title":"AI-gile: tîma te ya pêşdebirinê ya AI, li ser yek tabloyê","index.description":"AI-gile tabloyeke kanban e ji bo tîmên kodkirinê yên AI. Ew dixebitin dema tu radizê; ji te re yek komek kurt dimîne: tiştên ku divê biryar bidî, biceribînî û qebûl bikî.","hero.logoAlt":"Îkona tabloya AI-gile","hero.h1.html":"Tîma te ya pêşdebirinê ya AI, li ser yek&nbsp;tabloyê.","hero.alpha":"🐣 Pre-alpha ya girtî","hero.alphaTitle":"Zû û nîvco: spas ji bo ceribandinê!","hero.lede":"Ew dest bi çêkirinê dikin dema tu radizê. Tu şiyar dibî û komek kurt dibînî: çend pirs, çend tiştên ji bo ceribandinê, yek an du almasên mor. Bitikîne, qebûl bike, vegere qehwa xwe.","dl.windows":"Sepana Windows","dl.browser":"Di gerokê de bimeşîne","dl.messenger":"📱 Messenger ji bo telefona te","dl.soon":"Zû tê","dl.notify":"🔔 Gava vebû min agahdar bike","dl.notifySmall":"Alpha an beta","hero.secondary":"Agile, lê tîm qet qehweya stand-up naxwaze. (Dîsa jî stand-up çêdikin.)","pitch.h2":"AI-gile bi çiqas peyvan bixwazî","pitch.lede":"Dirêjahiyekê hilbijêre, ji yek peyvê heta 144. Her dirêjahî danasînek taybet e, ji bo wê mezinahiyê hatiye nivîsandin. Sliderê kaş bike an tuşên tîran bikar bîne.","pitch.rangeLabel":"Dirêjahî bi peyvan","pitch.dice":"🎲 guhertoyeke din","pitch.words.one":"{n} peyv","pitch.words.other":"{n} peyv","pitch.letters.one":"{n} tîp","pitch.letters.other":"{n} tîp","pitch.chars.one":"{n} nîşan","pitch.chars.other":"{n} nîşan","count.line.html.one":"{n} kart niha li ser tabloyê ye","count.line.html.other":"{n} kart niha li ser tabloyê ne","people.humans.html.one":"👥 {n} mirov","people.humans.html.other":"👥 {n} mirov","people.agents.html.one":"🤖 {n} ajan","people.agents.html.other":"🤖 {n} ajan","people.working.html.one":"⚡ {n} niha dixebite","people.working.html.other":"⚡ {n} niha dixebitin","pre.title":"AI-gile: li vir tiştek tê avakirin","pre.description":"Li vir tiştek tê avakirin. Tabloyek ku tîmên AI tiştê tu dixwazî ava dikin, û di rê de fêrî te dikin. Niha pre-alpha ya girtî ye bi hevalan re.","pre.h1":"Li vir tiştek tê avakirin. 🤫","pre.line":"Tabloyek ku tîmên AI tiştê tu dixwazî ava dikin, û di rê de fêrî te dikin. Niha pre-alpha ya girtî ye bi hevalan re.","pre.btn":"🔔 Gava vebû min agahdar bike","pre.peek":"Li pişt camê: tabloya rastîn, rasterast. Her kart xêzeke rengîn e.","pre.peekFake":"Li pişt camê: tabloyek di kar de wiha xuya dike.","features.aria":"Ew çi dike","f.pile.h":"Yek komek ji bo te","f.pile.html":"<b>Ji bo te</b> her tiştê ku li benda te ye ji hemû projeyan digire: pirs, tiştên ji bo ceribandinê, karên ku tenê mirov dikare bike. Rêza te dibêje çi paşê ye û çiqas dikişîne.","f.sleep.h":"Tîmên ku dema tu radizê dixebitin","f.sleep.p":"Her proje Lead û tîmek ajanên AI heye. Li ser kartekê şirove bike, tîm şiyar dibe, kar dike û bi gavên ku mirovekî westiyayî jî bişopîne vedigerîne.","f.tester.h":"Ceribînerê AI pêşî kontrol dike","f.tester.p":"Berî ku tiştek bigihîje te, ceribîner gavan di kopiyek sepanê de dişopîne û tiştê dîtiye bi dîmenek ekranê nîşan dide. Yên derbasbûyî bi lez bibîne û bi yek tikandinê qebûl bike.","f.proof.h":"Delîl, ne soz","f.proof.p":"Her radestkirin nîşan dide çi guherî: pelan, cudahiyan, dîmenên ekranê. Pêdivî nake ku tu her sepanê vekî da ku bibînî ma qediyaye.","f.chat.h":"Bi Leadên xwe re bipeyive","f.chat.p":"Tabloyeke wekî Discord: ji bo her projeyê yek îkon, ji bo tiştên ku te dixwazin almasên mor. Ji Leadekî re ramanekê binivîse; ew wê dike kart û plan, bi bişkoka ✅ Dest pê bike.","f.tidy.h":"Xwe bi xwe rêkûpêk dike","f.tidy.p":"Kartên girêdayî dibin yek, sernavên tevlihev tên rastkirin, û kontrola token kodê sivik dihêle. Kêmtir tişt ji bo guhertinê, kêmtir tişt ji bo fikirînê.","f.private.h":"Ya te, li ser komputera te","f.private.li1":"Tablo li ser komputera te ya xwe dimeşe û tenê bersiva te dide.","f.private.li2":"Peyamên taybet ên di navbera mirovan de ji dawiyê heta dawiyê şîfrekirî ne.","f.private.li3":"Ne hesab, ne şopîner, ne cookie.","f.lang.h":"Bi zimanê te","f.lang.p":"Zêdetirî 120 ziman, ji Holendî, Weylsî û Japonî heta pirate, Yoda û Klingon, bi vegera bilez bo Îngilîzî ji bo termên pîşeyî.","f.service.h":"Ji ramanekê heta xizmeteke rastîn","f.service.p":"Te bi AI tiştek ava kir ku niha mirov bi kar tînin? Wê wek xizmet nîşan bike û pano alîkariya te dike ku tu wê baş bimeşînî: kontrolên xebitînê, rûpeleke statûyê ya giştî, bûyer bi raporekê, guhertinên ku Here dixwazin, kopiyên ewlehiyê yên ku her roj tên kontrolkirin. Alîkarî her gavê di rê de fêr dike.","msgr.h2":"AI-gile Messenger: tîma te di bêrîka te de","msgr.p1":"Bêyî ku tabloyê vekî bi tîma xwe ya AI re bipeyive. Bi Leadên projeyên xwe û hevalên xwe re biçete, gavên testê yên kartekê bibîne û bersiv bide, hemû ji telefona xwe.","msgr.p2":"Ji bo girêdanê, kodeke QR li ser tabloya xwe skan bike. Cara yekem e? Chateke demo ya dostane dê te bigerîne.","msgr.when":"Pêşî Android, paşê guhertoyeke webê ji bo telefonan û iPhone.","msgr.who":"Leadê projeya te","msgr.b1":"Rastkirina moda tarî amade ye. Tu gavên testê dixwazî?","msgr.b2":"Erê, ji kerema xwe!","msgr.b3":"1. Mîhengan veke. 2. Tarî hilbijêre. Rast xuya dike?","tl.aria":"Rêzkirina demê ji gotûbêja yekem heta nexşerêyê","tl.h2":"Ji gotûbêja yekem heta tiştê ku tê","tl.lede":"Roj û demên rast, di herêma demê ya te de. Piştî îro ew plan e, bê roj sozdayî.","tl.today":"Îro","tl.planned":"plankirî","tl.doing":"di xebatê de","tl.cards.one":"{n} kart","tl.cards.other":"{n} kart","join.h2":"Tevlî bibe","join.lede":"AI-gile ji hêla zilamekî ecêb ê bi rih, bi AuDHD û çend şerên bi tenduristiya derûnî re, û hejmarek mezin ajanên sebirdar ve tê çêkirin. Niha taybet e, di alphayeke girtî de bi hevalan re. Dixwazî gava vebû biceribînî?","join.btn":"Eleqeyê tomar bike","join.small":"Em ê e-name bişînin, tiştek din na","footer.tag":"AI-gile. Bê şopîner, bê cookie, bê qehweya stand-up.","footer.licence":"Lîsansa karsaziyê","footer.status":"Rewş","footer.privacy":"Em çi diparêzin","footer.thanks":"Bang bi saya ChilledChat","form.sending":"Tê şandin…","form.failed":"Nebû: paşê dîsa biceribîne.","form.offline":"Gihîştina AI-gile nebû: paşê dîsa biceribîne.","form.keep":"Em vê tenê ji bo bersivdana te bi kar tînin, paşê jê dibin. Bê şopîner, bê cookie.","form.keepLink":"Em çi diparêzin","interest.title":"AI-gile: gava alpha vebû min agahdar bike","interest.description":"E-name xwe bihêle da ku bibihîzî gava alpha an beta ya girtî ya AI-gile vebe.","interest.h1":"🔔 Gava vebû min agahdar bike","interest.lede":"AI-gile di pre-alphayeke girtî de ye. E-name xwe bihêle û em ê carekê binivîsin, gava ji bo te cih hebe.","interest.email":"E-nameya te","interest.which":"Kîjan ceribandin?","interest.alpha":"Alpha ya girtî: zû, hişk, gelek guhertin","interest.beta":"Beta: aramtir, paşê","interest.both":"Yek ji wan, ya ku pêşî were","interest.submit":"Min têxe lîsteyê","interest.thanks":"Spas! Tu di lîsteyê de yî.","licence.title":"AI-gile: lîsansa karsaziyê","licence.description":"AI-gile di karsaziya xwe de bi kar tînî? Lîsansa karsaziyê ya belaş bixwaze.","licence.h1":"📜 Lîsansa karsaziyê","licence.lede":"AI-gile li ser kar bi kar tînî? Ji me re bêje tu kî yî û tu çi dikî. Heke ew qenciyekê dike, lîsans belaş e.","licence.company":"Şirket","licence.website":"Malper","licence.what":"Tu çi dikî","licence.how":"Çawa alîkariya cîhanê dike","licence.email":"E-name","licence.submit":"Daxwaz bike","licence.thanks":"Spas! Em ê bi e-name bersiv bidin.","status.title":"Rewşa AI-gile","status.h1":"Rewşa AI-gile","status.quiet":"Her tişt aram e","status.intro":"Gelo AI-gile niha dixebite? Ev rûpel her 5 deqîqeyan malper, parvekirina tabloyan, bang û daxistinê kontrol dike.","status.up":"Dixebite (di {ms} ms de bersiv da)","status.slow":"Bersiva kontrola dawî neda, dîsa tê ceribandin","status.down":"Rawestiyaye: bersiva du kontrolên dawî neda","status.svc.web":"Malper","status.svc.web.offers":"Ev malper: AI-gile çi ye, û forma eleqeyê","status.svc.boards":"Parvekirina tabloyan","status.svc.boards.offers":"Tabloyên giştî, peyamên di navbera hevalan de û vexwendin","status.svc.calls":"Bang","status.svc.calls.offers":"Deng, vîdyo û parvekirina ekranê di AI-gile de","status.svc.download":"Daxistin","status.svc.download.offers":"Sazkerê Windowsê û girêdanên vexwendinê","status.checking":"Tê kontrolkirin…","status.offline":"Niha nayê gihîştin xizmeta rewşê (dîsa dixebite)","status.updated":"{ago} nûkirî","status.justNow":"niha","status.min":"{n} xulek berê","status.hours":"{n} saet berê","status.days":"{n} roj berê","privacy.title":"AI-gile: em çi diparêzin","privacy.h1":"Em çi diparêzin","privacy.lede":"Bi kurtî: tenê tiştê tu ji me re dişînî, û ne ji bo demeke dirêj.","privacy.only":"Tenê tiştê tu ji me re dişînî: tiştê tu di formê de dinivîsî, wek e-nameya xwe. Tiştekî din li ser te tune.","privacy.sealed":"Ew tê mohrkirin da ku serverê me nikaribe wê bixwîne: di geroka te de, berî ku derkeve (li ser gerokeke kevntir, gava ku digihîje). Tenê tabloya me ya xwe dikare wê veke.","privacy.server":"Gava ku digihîje tabloya me, ji serverê tê jêbirin. Tiştê ku piştî 30 rojan hê li wir be jî, dîsa tê jêbirin.","privacy.board":"Em wê tenê heta ku me bersiva te da li ser tabloya xwe dihêlin, paşê li wir jî jê dibin.","privacy.none":"Bê şopîner, bê cookie, bê analîtîk.","privacy.local":"Ziman û hilbijartina te ya ronî an tarî di geroka te ya xwe de dimînin. Ew qet ji me re nayên şandin.","privacy.ask":"Dixwazî zûtir were jêbirin? Bersiva e-nameya me bide û ji me re bêje.","live.h2":"Bibîne çawa tê avakirin, rasterast","live.caption":"Her kart veşartî ye: hûn şêweya kar dibînin, ne peyvan.","live.watching.one":"rasterast: {n} dibîne","live.watching.other":"rasterast: {n} dibînin","live.last.now":"Karta dawî nû hat guhastin","live.last.min.one":"Karta dawî {n} deqe berê hat guhastin","live.last.min.other":"Karta dawî {n} deqe berê hat guhastin","live.last.hour.one":"Karta dawî {n} saet berê hat guhastin","live.last.hour.other":"Karta dawî {n} saet berê hat guhastin","live.last.day.one":"Karta dawî {n} roj berê hat guhastin","live.last.day.other":"Karta dawî {n} roj berê hat guhastin","live.offline":"Tabloya rasterast hinekî dimîne. Zû dîsa werin.","live.cols":"Backlog|Ji bo kirinê|Di xebatê de|Tîm kontrol dike|Ji bo te ku test bikî|Ji bo tîmê|Qediya"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Radestkirî."]},{"n":2,"texts":["Kanbana robotan.","Ajanên rêkûpêk.","Raman, çêkirî."]},{"n":3,"texts":["Kanban ji robotan re.","Raman dibin taybetmendî.","Kanbana ajanan, belaş."]},{"n":5,"texts":["Tabloya kanban ku ajan dimeşînin.","Tu kartan dinivîsî. Ajan çêdikin.","Belaş, herêmî, ceribandî, hinekî henekî."]},{"n":8,"texts":["Tabloyeke kanban a belaş ku ajanên AI tê de dixebitin.","Ramanekê binivîse. Ajan çêdikin. Tu qebûl dikî.","Agile ji bo yek mirov û gelek robotên sebirdar."]},{"n":13,"texts":["Tabloyeke kanban li ser komputera te ku ajanên AI kartan hildidin û te serokê wan dihêle.","Ramanekê binivîse. Tîmek ajan wê çêdike. Ceribîner kontrol dike. Tu dibêjî erê.","Bê hesab, bê şopîner: tablo, çend robot û tu, yê ku biryarê dide."]},{"n":21,"texts":["AI-gile tabloyeke kanban e ji bo xebata bi ajanên kodkirinê yên AI re. Ew kartan hildidin; tu wan diceribînî û qebûl dikî.","Her proje Lead û tîmek ajanên AI distîne. Li ser her kartekê şirove bike û tîm dest bi kar dike.","Tabloyeke karên kesane ya belaş li ser komputera te ya xwe dimeşe. Karker robot in. Yê ku dibêje erê tu yî."]},{"n":34,"texts":["Tu ramanan datînî ser tabloyê. Tîmek ajanên AI wan dike taybetmendiyên ku dixebitin, diceribîne, û bi gavên ceribandinê vedigerîne. Tu tişt wekî qediyayî nayê hesibandin heya ku tu nebêjî.","AI-gile tabloyeke kanban a malê ye ku Rich bi alîkariyeke mezin a ajanên ku ew niha îdare dike çêkir. Belaş e, li ser komputera te dimeşe û bi hevalan re tê parvekirin, nayê firotin.","Tabloyeke kanban a asayî bifikire, bi stûnên ji Backlog heta Done, tenê kart ji aliyê ajanên AI ve têne hilgirtin. Pêşketinê radigihînin, gava asê dibin dipirsin, û her dem li benda tiliya te ya bi ber jor dimînin."]},{"n":55,"texts":["AI-gile tabloyeke kanban e ku tîma wê ji ajanên AI pêk tê. Her proje Leadek heye ku kar plan dike û alîkarên ku wê çêdikin. Gava taybetmendiyek amade be, ceribînerê AI wê diceribîne û dîmenek ekranê digire, paşê ew dikeve komeka te. Wê qebûl bike, an şirove bike û ew ê ji nû ve li ser bixebitin.","Ew bi riya yek kesî dest pê kir ku dixwest gelek rûniştinên kodkirinê yên AI di heman demê de bişopîne, û bû tabloyeke rast. Li ser makîna te dimeşe, hesabekî naxwaze û şopîner nîne. Ji bo heval û meraqdaran belaş e. Hê qediyayî nîne, ji ber vê yekê li bendê keviyên hişk û carinan şaşmayîneke biçûk be.","Ev guhertoya dilrast e. Hê jî divê ramanên te hebin, û hê jî divê tu encaman kontrol bikî. Tiştê ku AI-gile dike her tişta di navbera wan de ye: kartan di rêzê de digire, gava tu şirove dikî ajanê rast şiyar dike, tam nîşan dide çi guherî, û hemûyan di yek komeka kurt de ji te re kom dike."]},{"n":89,"texts":["AI-gile tabloyeke kanban a belaş e ku tu li ser komputera xwe dimeşînî. Li şûna mirovan, her proje tîmek ajanên AI heye: Leadek ku ramanên te dike kart û plan, û alîkarên ku kartan li gorî girîngiyê hildidin. Gava tiştek hat çêkirin, ceribînerê AI gavên ceribandinê dişopîne û tiştê dîtiye nîşan dide. Paşê di komekê de bi navê Ji bo te li bendê dimîne. Tu qebûl dikî, an şirove dikî û tîm dîsa hewl dide. Tu kart bêyî te nagihîje Done.","Çend taybetmendiyên ku dibe tu li bendê nebî. Nobedariya şevê stûna Ji bo kirinê dema tu radizê tijî dihêle, kartên ku bersiva te nahewînin hildibijêre. Hejmarkerê token nîşan dide ka ajan îro û vê hefteyê çiqas bikar anîn, û No Token Mode ji wan re dibêje xerc nekin. Tu dikarî ji hevalan re peyam bişînî, û peyamên taybet ji dawiyê heta dawiyê şîfrekirî ne. Tablo bi nêzîkî 120 zimanan dipeyive, di nav de Holendî, Flamî, pirate û Klingon. Tu yek ji wan ne bi pere ye, û kes naxwaze wê bifroşe te.","AI-gile projeyeke biçûk û kesane ye, ne şirket e. Rich dixwest çend projeyên kodkirinê yên AI bişopîne bêyî ku her sepanê veke, ji ber vê yekê wî û ajanan tabloyek ji bo vê çêkirin, paşê bi wê tabloyê ya mayî ya xwe çêkirin. Di pre-alphayeke girtî de ye, ango dixebite, bi piranî, ji bo çend hevalan. Rûpelek bihayan, bultena nûçeyan û plana mezinbûnê tune ne. Heke bikêr xuya dike, dikarî bipirsî ku gava hinekî bêtir vebû biceribînî."]},{"n":144,"texts":["AI-gile tabloyeke kanban e ji bo yek mirov û gelek ajanên AI. Li ser komputera te ya xwe dimeşe û bi tevahî belaş e. Tu proje zêde dikî, û her proje Leadek û tîmeke biçûk distîne. Tu bi Lead re dipeyivî, hinekî wekî Discord, û ramanekê vedibêjî; Lead wê dike kart û plan, paşê li bendê dimîne heta tu Dest pê bike bitikînî. Tîm kartan li gorî girîngiyê dikişîne, bi rêzefermaneyeke hêsan a ji bo modelên zimanî hatî çêkirin. Berî ku tiştek ji te re vegere, ceribînerê AI gavan di kopiyek sepanê de dişopîne û dîmenek ekranê lê zêde dike. Karê qediyayî bi pelên guherî û cudahiyê re dikeve komeka te. Tu qebûl dikî, an şirove dihêlî û tîm şiyar dibe û dîsa hewl dide. Tenê tu dikarî kartekê bibî Done. Hemû ev li ser komputera te ne, bê hesab, bê şopîner, bê cookie.","Rojek bi AI-gile re, bi qasî. Êvarê tu çend şirovan dihêlî: ev bişkojk di cihê şaş de ye, ew lîste divê were rêzkirin, gelo em dikarin moda tarî hebin. Tu diçî razanê. Ajan şirovan dixwînin, guhertinan çêdikin, diceribînin û vedigerînin. Heke stûna Ji bo kirinê vala bibe, nobedariya şevê wê ji backlogê bi kartên ku bersiva te nahewînin tijî dike. Serê sibê yek komek kurt maye: du pirs û çend tiştên ji bo ceribandinê, her yek bi gavên ku mirovekî xewalû jî bişopîne û dîmenek ekranê ku dixebite. Tu bi ser wan de diçî, yên baş qebûl dikî û yên mayî vedigerînî. Hejmarkerê token nîşan dide ku ev hemû çiqas bikar anî, û No Token Mode ji bo hefteyên hişk e. Paşê tu taştê dixwî, ku ajan hê nikarin alîkariya wê bikin.","Pêşî, AI-gile çi nîne. Ne startup e, ne ji bo firotinê ye, û kes daneyên te kom nake. Tabloyeke belaş e ku li ser komputera te dimeşe, bê hesab, bê şopîner û bê cookie. Ew çi ye: yek cihê rêkûpêk ji bo dîtina hemû projeyên kodkirinê yên AI bi carekê, bi tîmek ajanan ku kartan dike û te ku biryaran dide. Kartên girêdayî tevhev dike, sernavên tevlihev rast dike, û çavdêriya sivikbûna kodê dike. Bi nêzîkî 120 zimanan dipeyive, ji Holendî û Flamî heta pirate û Klingon. Heval dikarin ji hev re peyam bişînin, taybet û şîfrekirî. Ji hêla Rich û hejmarek mezin ajanên sebirdar ve hatiye çêkirin, bi piranî bi karanîna xwe. Di pre-alphayeke girtî de ye, ji ber vê yekê li hin deveran hişk e. Heke xweş xuya dike, bi rêzdarî bixwaze û dibe ku zû têkevî."]}],"quips":{"1":"Yek peyv. Zîrek. Dibe ku pir zîrek.","3":"Sê peyv. Ji piraniya rûpelên hilberan jixwe dilrasttir.","8":"Heşt peyv. Hê jî ji stand-upê kurttir.","21":"Dirêjahî, bi awayê, xalên çîrokê ne. Bê guman ew in.","55":"Pêncî û pênc peyv. Du kart qediyan dema te ev dixwend.","144":"Ev ya dirêj e. 233 tune ye. Ajan çûne razanê."}},"timeline":{"first-idea.name":"Ramana yekem","first-idea.line":"Gotûbêja pir pêşîn, berî ku kod hebe.","first-board.name":"Tabloya yekem","first-board.line":"Tabloyek ku çêkirina xwe dişopîne: kart, stûn, kaşkirin û berdan, proje.","team-roles.name":"Tîm û rol","team-roles.line":"Profîlên ajanan, şablonên tîmê, cih û kê çi dike.","install.name":"Sazkirin û weşan","install.line":"Zipek ku heval dikare saz bike, nûkirinên xweber, kanal û vegerandin.","usage-saver.name":"Teserûfa bikaranînê","usage-saver.line":"Bipîve ka meşandin çiqas dike, kodê sivik bihêle, sînorê xwe biparêze.","friends.name":"Heval û parvekirin","friends.line":"DMên taybet, relayeke şîfrekirî, vexwendin, rol û projeyên hevpar.","languages.name":"Ziman","languages.line":"Her nivîsa ekranê di pelê zimanekî de, bi Holendî û Flamî pêşî.","ai-tester.name":"Ceribînerê AI","ai-tester.line":"Ceribînerek her radestkirinê pêşî kontrol dike û tiştê dîtiye nîşan dide.","website.name":"Malper","website.line":"aigile.lol, rûpela teaser û ev rêzkirina demê.","streaming.name":"Chat û streaming","streaming.line":"Discord, Twitch, OBS, moda streamer, GIF û emoji.","no-ai.name":"Guhertoya bê AI","no-ai.line":"Tabloyek ji bo kesên ku bê AI kod dikin, û tabloyên giştî.","night-watch.name":"Nobedariya şevê","night-watch.line":"Nobedar û Scrum Master tîman li ser kar dihêlin dema tu radizê.","p-more.name":"Hemû yên din","p-more.line":"Ramanên biçûktir ku hê li benda rêza xwe ne.","p-android.name":"Telefon û Android","p-android.line":"Bi telefonê bigihîje tabloya xwe, paşê bi sepana Android a xwecihî.","p-release.name":"Alpha û pê ve","p-release.line":"Alpha ya girtî, malpera zindî, paşê beta.","p-languages.name":"Zimanên zêdetir","p-languages.line":"Zêdetirî sed ziman, û moda binavbûnê ji bo fêrbûyan.","p-engines.name":"Motorên AI yên zêdetir","p-engines.line":"Ji bo her ajanî Claude, Codex an Gemini hilbijêre.","p-pro.name":"Pratîka pispor","p-pro.line":"Etîketên rîskê, deriyên merge, kartên bûyerê û asteng-parastinan.","p-self.name":"Xwedîkirina te","p-self.line":"Moda westiyayî, bîranînên xwe-lênihêrînê û 4:20.","p-servers.name":"Server û mezinbûn","p-servers.line":"Mîhengên serverê yên giştî, rol û plankirina mezinbûnê.","p-livestream.name":"Zêdeyên streamingê","p-livestream.line":"Chata Twitch, emojiyên taybet û dîtina zindî ya giştî."},"words":{"button":"📖 Termên pîşeyî","h":"📖 Peyv rave kirî","intro":"Peyvên ku tu di AI-gile de dibînî, bi zimanekî sade: avakirin, bi ewlehî guhertin, ji bo kesên ku bi kar tînin xebitandina wê ya domdar, û wek tîm bi AI re xebitîn.","search":"Li peyvekê bigere…","none":"Tu peyv bi vî rengî nîne.","close":"Bigire","count":{"one":"{count} peyv","other":"{count} peyv"},"groups":[{"id":"build","name":"🛠️ Avakirin"},{"id":"change","name":"🔀 Bi ewlehî guhertin"},{"id":"run","name":"🛎️ Xizmetek rêvebirin"},{"id":"team","name":"🤝 Wek tîm xebitîn (û bi AI re)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Peldanka kodê ya projeyê û dîroka wê ya tije ya commitan, bi gelemperî li GitHub jî tê parastin.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Rêzeke xebatê ya cuda di kodê de, da ku bêyî dest dayîna guhertoya sereke guherîn bêne çêkirin.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Wêneyekî tomarkirî yê kodê, bi nîşeyeke kurt a ku çi guherî. Tu her gav dikarî vegerî yekê.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Şandina wêneyên tomarkirî (commit) ji vî komputerî ji bo GitHub, da ku paşvekişîn û parvekirî bin."},{"id":"merge","g":"build","word":"Merge","text":"Zêdekirina guherînên şaxekê dîsa li guhertoya sereke."},{"id":"pr","g":"build","word":"Pull request","text":"Xwestina ku guherînên şaxekê bêne kontrolkirin û bi guhertoya sereke re bêne yekkirin.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Paqijkirina kodê bêyî guhertina ya ku dike: pelên biçûktir, navên zelaltir, dubarekirina kêmtir."},{"id":"bug","g":"build","word":"Bug","text":"Tiştek ku wekî divê naxebite.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Ceribandina xebatekê ya qediyayî da ku berî qebûlkirinê bê dîtin ka ew tiştê hatiye xwestin dike.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Kurteya quality assurance, yanî misogerkirina kalîteyê: kontrolên otomatîk ên ku berî ku tiştek zindî biçe dixebitin. Dema QA sor be, tiştek têk çûye, û heta ku neyê rastkirin nikare zindî biçe.","also":["kontrola kalîteyê","misogerkirina kalîteyê"]},{"id":"deploy","g":"change","word":"Deploy","text":"Guhertoyeke nû zindî kirin, mînak li ser serverekî ku mirov lê bi kar tînin."},{"id":"release","g":"change","word":"Berdan","text":"Pakêteke bi nav a karê qedandî ku bi hev re zindî diçe, bi notên kurt ka çi guherî. 🚀 Berdan notan ji kartên qedandî dinivîse.","also":["berdan","release"]},{"id":"rollback","g":"change","word":"Vegerandin","text":"Dema guhertoyeke nû pirsgirêkan çêdike, vegera li guhertoya dawî ya ku dixebitî. Di AI-gile de ew ji gavên betalkirinê yên ku li ser her guhertinê hatine nivîsandin lîsteyeke kontrolê çêdike.","also":["rollback","vegere","hat vegerandin"]},{"id":"live","g":"change","word":"Zindî","text":"Guhertoya rastîn a ku mirov bi kar tînin, ne kopiyeke ji bo ceribandinê. Pêşdebir jê re production jî dibêjin.","also":["production","hilberîn"],"noTip":1},{"id":"change","g":"change","word":"Guhertin","text":"Guhertineke plankirî li tiştekî ku mirov pê bawer dikin, pêşî tê nivîsandin: çi, çima, risk, kengî û çawa were betalkirin. Bi 🔀 Guhertinekê bixwaze dest pê bike.","also":["guhertin","daxwaza guhertinê"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Tiştek ku dikare xelet biçe, li gor ka çiqas îhtîmal e û çiqas xirab dibe tê pûankirin. ⚠️ Risk wan di yek lîsteyê de digire, pûana herî bilind pêşî, her yek bi dîrokeke ji bo dîsa nihêrînê.","also":["risk","tomara riskan"]},{"id":"chgwin","g":"change","word":"Pencereya guhertinê","text":"Demên ku guhertin dikarin zindî biçin, mînak êvareke Sêşemê ya aram. Li derveyî pencereyê karta guhertinê nayê qedandin, heke ne rewşeke acîl be.","also":["pencereyên guhertinê","change window"]},{"id":"gonogo","g":"change","word":"Here / Neçe","text":"Dengdaneke bilez berî ku guhertinek zindî biçe: her kesê ku divê erê bike dibêje Here an Neçe. Ew tenê dema ku hemû li hev bikin pêş de diçe.","also":["go/no go","go-no-go","here/neçe"]},{"id":"approval","g":"change","word":"Erêkirin","text":"Li benda \"erê\" mayîn berî ku kar dest pê bike. Kartek ku hevalek vedike, an guhertinek, di ✅ Erêkirin de li bendê dimîne heta ku tu wê erê bikî an red bikî.","also":["erêkirin","pejirandin"]},{"id":"quiettime","g":"change","word":"Dema bêdeng","text":"Demek, wek weşaneke zindî, demoyek an şev, ku tê de tiştek zindî naçe. Tîm xebat û ceribandinê didomînin, lê zindî çûn li bendê dimîne heta ku ew bi dawî bibe. Li cihên din jê re cemidandina guhertinan (change freeze) tê gotin.","also":["demên bêdeng","change freeze","cemidandina guhertinan"]},{"id":"service","g":"run","word":"Xizmet","text":"Tiştek ku te ava kiriye û mirov pê bawer dikin, wek malperek an sepanek, ku lê tê miqatekirin da ku bixebite. \"Ev proje xizmetek e\" nîşan bike û bibêje ka ew çi pêşkêş dike, kî bi kar tîne û kî bersivdar e.","also":["xizmet","service"]},{"id":"uptime","g":"run","word":"Kontrola xebitînê","text":"Kontroleke otomatîk, her çend deqeyan carekê, ka xizmeta te hîn bersiv dide. Heke çend caran li pey hev têk biçe, AI-gile bi xwe karteke bûyerê vedike.","also":["uptime","dema çalakbûnê"]},{"id":"statuspage","g":"run","word":"Rûpela statûyê","text":"Rûpeleke giştî ku nîşan dide ka xizmetek dixebite (kesk, porteqalî an sor) bi nûçeya dawî re, da ku kesên ku bi kar tînin li wir binêrin li şûna pirsînê.","also":["rûpelên statûyê","status page"]},{"id":"incident","g":"run","word":"Bûyer","text":"Tiştek ku niha ji bo kesên ku bi kar tînin şikestî ye, wek malperek ku ketiye. Karta 🔥 bûyerê dikeve serê rêzê: dîsa xebitandina wê berî her tiştî tê.","also":["bûyera acîl","bûyer","incident"]},{"id":"major","g":"run","word":"Bûyera mezin","text":"Bûyereke mezin: gelek kes bandor bûne, an pere an dane di xeterê de ne. Bişkokek hemû tîman dide ser wê (swarm), kesê bersivdar şiyar dike û her 30 deqeyan nûkirineke statûyê dixwaze.","also":["bûyerên mezin","major incident"]},{"id":"oncall","g":"run","word":"Bersivdarî","text":"Bûna kesê ku bersiv dide dema tiştek dişkê, şevê jî. Her xizmetekê endamekî tîmê yê bersivdar heye ku ji bo bûyerên wê pêşî tê şiyarkirin.","also":["bersivdar","on call","on-call"]},{"id":"replyby","g":"run","word":"Dema bersivdanê","text":"Kartek çiqas dikare li benda bersiva yekem bimîne, mînak saetek ji bo bûyerekê. Piştî wê saeteke sor distîne, da ku tiştek bi bêdengî neyê jibîrkirin. Jê re armanca bersivdanê jî tê gotin.","also":["demên bersivdanê","armanca bersivdanê","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Nihêrîneke kurt a paşve piştî bûyerekê: çi qewimî, çi alîkarî kir û çi divê were guhertin, bêyî ku kes were sûcdarkirin. Bêyî wê bûyer nayê girtin.","also":["post-mortem","postmortem","nirxandina piştî bûyerê"]},{"id":"problem","g":"run","word":"Pirsgirêk","text":"Sedema veşartî ya li pişt yek an çend bûyeran. Karta 🧩 pirsgirêkê bûyerên ku dîsa û dîsa vedigerin kom dike, da ku sedem were dîtin û bi carekê were rastkirin.","also":["pirsgirêk","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Sedema bingehîn","text":"Sedema rastîn a ku tiştek şikest, ne tenê ya ku te dît xelet diçe. Sedema bingehîn rast bike û bûyer êdî venagere.","also":["sedemên bingehîn","root cause"]},{"id":"workaround","g":"run","word":"Çareya demkî","text":"Rêyek ji bo xebitandina tiştan heta ku rastkirina rastîn amade bibe, wek ji nû ve destpêkirina tiştekî dema ku asê dibe. Ew li ser karta pirsgirêkê tê nivîsandin da ku kes neçar nemîne dîsa bibîne.","also":["çareyên demkî","workaround"]},{"id":"knownerror","g":"run","word":"Çewtiya nas","text":"Pirsgirêkek ku sedema wê tê fêmkirin û çareyeke demkî heye, lê hîn nehatiye rastkirin. 🧩 Çewtiyên nas wan rêz dike, da ku her kes çareya demkî bi kar bîne li şûna ku dîsa bikole.","also":["çewtiyên nas","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Rêwerzên gav bi gav ji bo rastkirina cureyekî nas ê pirsgirêkê, da ku her car bi heman awayî û bilez were kirin. Piştî bûyereke mezin tîm dikare yekê pêşniyar bike ku tu OK bikî.","also":["runbook","rêbernameya karan"]},{"id":"backup","g":"run","word":"Kopiya ewlehiyê","text":"Kopiyeke tomarkirî ya daneyên te yên berê, ji bo ku pê bikevî heke tiştek winda bibe an xera bibe. AI-gile her roj kopiyeke ewlehiyê ya panoyên te çêdike.","also":["backup","kopî","kopiyên ewlehiyê"]},{"id":"restore","g":"run","word":"Vegerandina daneyan","text":"Daneyan ji kopiya ewlehiyê paşde danîn. Kopiyek tenê dema ku tu dizanî dikare were vegerandin bi rastî tê hesibandin, ji ber vê yekê hêja ye ku carinan biceribînî.","also":["vegerîne","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Raman û xebatên ku hê nehatine plankirin. Heta ku neçin Ji bo kirinê li wir tiştek nayê kirin."},{"id":"sprint","g":"team","word":"Sprint","text":"Demeke kurt a xebatê (pir caran hefteyek an du) bi komeke kartên lihevkirî ku divê bêne qedandin.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Kontrolekî bilez: her endamê tîmê çi kir, piştre dê çi bike, û çi pê re disekine.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Tabloyeke bi stûnan (Ji bo kirinê, Di xebatê de, Qediya) ku kart dema xebat çêdibe ji çepê ber bi rastê diçin."},{"id":"wip","g":"team","word":"WIP limit","text":"Xebata di nav pêşveçûnê de: herî zêde çend kart divê di stûnekê de bin, da ku tîm berî destpêkirina yên din tiştan biqedîne.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Lîsteya kurt a tîmê ka \"qediya\" çi tê wateyê, wek ceribandî û ravekirî, berî ku kartek bigihîje te. Cêwiya wê, Definition of Ready, dibêje kengî kartek têra xwe zelal e ku dest pê bike.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Stûna ceribandinê","text":"Kartên qedandî yên ku li benda ceribandina te ne, yek li pey yekê. Yekê qebûl bike an bi notekê paşde bişîne, û ya din tê.","also":["stûna ceribandinan","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Nihêrînek li ser ka tîm çawa dixebite, ji bo ku li ser tiştekî ku baştir bikin li hev bikin. Di AI-gile de retro guhertinekê di awayên xebatê yên tîmê de pêşniyar dike, û tu dibêjî Here an Hîn na.","also":["retro","retrospektîf"]},{"id":"peerreview","g":"team","word":"Nirxandina hevalan","text":"Cotek çavên din: AI'yeke din karê her kartê berî ku bigihîje te kontrol dike, da ku kêmtir xelet derbas bibin.","also":["peer review","code review","nirxandina kodê"]},{"id":"swarm","g":"team","word":"Swarm","text":"Her kes dest dide: her tîm karê din datîne da ku alîkariya projeyeke bilez bike heta ku çareser bibe. Di vê navberê de projeyên din li bendê ne.","also":["swarm","swarming","pez"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Kesê ku kar diherikîne: kartên asêmayî dibîne, tîman han dide û tiştên li benda te bîra te tîne. Di AI-gile de Lead Scrum Master vê li ser hemû projeyan dike.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AIyek ku bi tena serê xwe li ser peywirekê dixebite: kodê dixwîne, guherînan çêdike, kontrolan dixebitîne û rapor dide.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Yekeya ku bikaranîna AI pê tê hejmartin: bi qasî çend tîpên nivîsê yên xwendî an nivîsandî. Tokenên kêmtir, plana te ya mayî zêdetir.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Fermanek biçûk ku di dema diyarkirî de bi xwe dixebite, mînak dema danişîneke AI dest pê dike, da ku tîm şîroveyên te bibihîze.","also":["hooks"]}]}};
